// ============================================================ ROMA, AÑO 80 d.C.: contenido
// Mismo formato que NPCS/SRC/ESSAYS de Atenas. romaSetup() sustituye el contenido de Atenas por este antes de construir el mundo.
const TOGA={chiton:'#efe9dc',toga:true,himation:'#f3eee2'};
const ROMA_NPCS=[
{id:'marcial',name:'Marco Valerio Marcial',title:'Poeta de epigramas',glyph:'M',look:Object.assign({},TOGA,{hair:'#3a2a1e'}),
 cat:'Cultura',lesson:'El Libro de los espectáculos',where:'Ante la entrada oeste del Anfiteatro Flavio',
 summary:'Marco Valerio Marcial (c. 40-104), nacido en Bílbilis (Hispania), vive en Roma desde el 64. Para la inauguración del Anfiteatro Flavio en el 80 compuso el Libro de los espectáculos, epigramas breves que celebran los juegos de Tito: cacerías, combates y escenas mitológicas en la arena. Sus epigramas retratan la vida diaria de Roma con humor y mordacidad.',
 intro:'¡Ah, otro forastero que viene a ver los juegos! Soy Marco Valerio Marcial, de Bílbilis, en Hispania, aunque llevo dieciséis años en Roma. Escribo epigramas: poemas cortos, con veneno en la cola. Estos días escribo sobre lo que pasa ahí dentro: el anfiteatro más grande que ha visto el mundo.',
 topics:[
  ['¿Qué estás escribiendo?','Un librito para los juegos de inauguración: cien días de espectáculos que paga el emperador Tito. Un poema por cada maravilla: un elefante que se arrodilla ante el César, un rinoceronte que lanza un toro por los aires, una mujer que lucha contra un león… Empiezo diciendo que las pirámides de Egipto y las murallas de Babilonia ya pueden callarse: todo trabajo humano cede ante el anfiteatro del César.'],
  ['¿Qué pasó con Prisco y Vero?','Dos gladiadores luchaban sin que ninguno cediera, y el público pedía para ellos la libertad. Tito había puesto una regla: luchar hasta que uno levantara el dedo. Pero los dos lo levantaron a la vez, y el César les dio a ambos la espada de madera, el rudis, y la palma de la victoria. Lo cuento en uno de mis epigramas. Prisco anda por la arena; pregúntale.'],
  ['¿Cómo vive un poeta en Roma?','Mal, amigo. Me levanto al alba para ir a saludar a mis patronos con la toga, que pesa en verano, y a cambio me dan la espórtula: unas monedas o un poco de comida. Vivo en un tercer piso del Quirinal y subo muchas escaleras. Los libreros venden mis libros por cinco denarios y yo no veo ni un as. Pero todos me leen.']],
 quiz:{q:'¿Para qué ocasión escribió Marcial el Libro de los espectáculos?',a:['Para la inauguración del Anfiteatro Flavio por Tito en el año 80','Para el triunfo de Augusto tras Accio','Para los funerales de Nerón'],ko:'No. El Libro de los espectáculos celebra los juegos de inauguración del Anfiteatro Flavio, que Tito ofreció en el año 80.'}},

{id:'quintiliano',name:'Marco Fabio Quintiliano',title:'Maestro de retórica',glyph:'Q',look:Object.assign({},TOGA,{hair:'#6b6058',beard:false}),
 cat:'Cultura',lesson:'La formación del orador',where:'En la Basílica Julia, en el Foro',
 summary:'Quintiliano (c. 35-c. 100), nacido en Calagurris (Calahorra, Hispania), fue el primer profesor de retórica pagado por el Estado, con un sueldo que le asignó Vespasiano. Defendía una educación completa desde la infancia, sin castigos físicos, para formar al orador ideal: «un hombre bueno, hábil en el hablar». Lo expuso más tarde en su Institución oratoria.',
 intro:'Bienvenido. Soy Marco Fabio Quintiliano. Enseño retórica aquí, en Roma, y el emperador Vespasiano me asignó un sueldo de cien mil sestercios al año, pagado por el erario: el primer maestro pagado por el Estado. Mis alumnos hablan después en estos mismos tribunales de la Basílica Julia.',
 topics:[
  ['¿Qué enseñas?','A hablar bien, que es lo mismo que pensar bien y vivir bien. El orador perfecto, decía Catón, es un hombre bueno hábil en el hablar. No basta con la técnica: hace falta saber de todo, historia, derecho, filosofía, poesía. Empezamos con la gramática y los poetas; luego vienen los ejercicios: narraciones, alabanzas, discursos sobre casos inventados. Y mucha memoria.'],
  ['¿Pegas a tus alumnos?','Nunca. Los azotes son cosa de esclavos y no enseñan nada: humillan y endurecen. Un niño aprende jugando y por emulación, si el maestro sabe despertar su ambición. Y el aprendizaje empieza en la cuna: que la nodriza hable bien, que el pedagogo sea culto. Los errores de habla que se aprenden de niño cuestan años quitarlos.'],
  ['¿Dónde se habla en público en Roma?','Aquí mismo: en la Basílica Julia se reúne el tribunal de los centunviros, que juzga herencias. Hay cuatro salas a la vez, y a veces los oyentes aplauden tanto que se oye en la sala de al lado. En el Senado ya no se decide tanto como antes; desde Augusto, el que manda es el príncipe. Pero en los tribunales la palabra todavía puede salvar o hundir a un hombre.']],
 quiz:{q:'¿Por qué fue novedoso el puesto de Quintiliano?',a:['Fue el primer maestro de retórica con un sueldo pagado por el Estado','Fue el primer romano que enseñó en griego','Fue el primer senador que escribió poesía'],ko:'No. Vespasiano le asignó un sueldo público: fue el primer profesor de retórica pagado por el erario en Roma.'}},

{id:'josefo',name:'Flavio Josefo',title:'Historiador judío',glyph:'I',look:{chiton:'#e9dfc8',himation:'#3a4a6a',beard:true,hair:'#2a1a12'},
 cat:'Historia',lesson:'La guerra judía y el Templo de la Paz',where:'En el Templo de la Paz, junto a los foros',
 summary:'Josefo (37-c. 100), sacerdote de Jerusalén y jefe rebelde en Galilea, se rindió a Vespasiano en el 67 y le predijo que sería emperador. Liberado y con el nombre de la familia Flavia, presenció la destrucción de Jerusalén en el 70 y escribió en Roma la Guerra de los judíos. Los objetos del Templo de Jerusalén, como el candelabro de siete brazos, se expusieron en el Templo de la Paz.',
 intro:'Shalom, forastero. Me llamaba Yosef ben Matityahu, sacerdote de Jerusalén. Ahora me llaman Flavio Josefo. Vivo en la antigua casa del emperador Vespasiano y escribo la historia de la guerra en la que mi pueblo lo perdió casi todo. Mira ahí dentro: el candelabro de oro de nuestro Templo está expuesto como un trofeo.',
 topics:[
  ['¿Cómo llegaste a Roma?','Dirigía la defensa de Galilea contra Roma. En Jotapata resistimos cuarenta y siete días; cuando cayó, me escondí en una cueva con otros cuarenta. Decidieron matarse antes que rendirse, y echamos suertes. Yo quedé entre los últimos y me entregué. Ante Vespasiano le dije que sería emperador. Dos años después lo era. Me liberó y llevo su nombre. Mis paisanos me llaman traidor; yo digo que solo vi antes que ellos lo que iba a pasar.'],
  ['¿Qué pasó con el Templo?','En el verano del 70, Tito, el hijo de Vespasiano, tomó Jerusalén tras un asedio terrible: hambre, fuego, facciones que se mataban entre sí dentro de las murallas. El Templo ardió. Yo lo vi desde las líneas romanas. Al año siguiente desfilaron aquí, en el triunfo, la mesa de los panes, las trompetas de plata y el candelabro de siete brazos. Ahora están en este Templo de la Paz. Paz, lo llaman.'],
  ['¿Qué es el Templo de la Paz?','Vespasiano lo inauguró hace cinco años con el botín de Judea. Es más un jardín que un templo: una gran plaza con pórticos, estanques y rosales, una sala con estatuas y pinturas griegas famosas traídas de todo el imperio, y una biblioteca. Los romanos vienen a pasear y a mirar obras de arte. Yo vengo a mirar el candelabro y a recordar.']],
 quiz:{q:'¿Qué se exponía en el Templo de la Paz que procedía de Jerusalén?',a:['El candelabro de siete brazos y otros objetos del Templo judío','La estatua de oro de Zeus de Olimpia','Los escudos de los galos de Alesia'],ko:'No. Vespasiano expuso en el Templo de la Paz el botín de la guerra de Judea, como el candelabro de siete brazos (menorá) del Templo de Jerusalén.'}},

{id:'epicteto',name:'Epicteto',title:'Esclavo y filósofo estoico',glyph:'E',look:{short:true,chiton:'#a89070',hair:'#3a2a1e',beard:true,staff:true},
 cat:'Filosofía',lesson:'Lo que depende de nosotros',where:'Junto a las Termas de Tito, en la ladera del Esquilino',
 summary:'Epicteto (c. 50-c. 135), nacido en Hierápolis de Frigia, fue esclavo de Epafrodito, liberto de Nerón, que le permitió estudiar con el estoico Musonio Rufo. Cojo, enseñaba a distinguir lo que depende de nosotros (juicios, deseos) de lo que no (cuerpo, bienes, fama), y que la libertad está en el interior. Ya liberado enseñó en Roma y luego en Nicópolis; su discípulo Arriano recogió sus enseñanzas.',
 intro:'No te apiades de mi pierna, forastero. Me llamo Epicteto, que en griego significa «adquirido»: soy esclavo de Epafrodito, el que fue secretario de Nerón. Mi amo me deja ir a escuchar al filósofo Musonio. Y te diré algo: soy más libre que muchos senadores que pasan por aquí en litera.',
 topics:[
  ['¿Cómo puede ser libre un esclavo?','De las cosas que existen, unas dependen de nosotros y otras no. Dependen de nosotros el juicio, el deseo, la aversión: lo que es obra nuestra. No dependen de nosotros el cuerpo, los bienes, la fama, los cargos. Mi amo puede encadenar mi pierna, pero ni Zeus puede encadenar mi voluntad. El que desea lo que no depende de él, ese es el verdadero esclavo.'],
  ['¿Qué le pasó a tu pierna?','Unos dicen que nací cojo; otros, que un amo me la retorció por diversión. Cuentan que yo le dije: «Si sigues, la romperás». Y cuando se rompió: «¿No te lo decía?». Sea como sea, la pierna no es asunto mío; lo que me corresponde es cómo lo llevo. No son las cosas las que nos perturban, sino las opiniones que tenemos sobre las cosas.'],
  ['¿Qué es el estoicismo?','Una filosofía que nació en Atenas, en la Stoa Pintada, con Zenón, hace casi cuatrocientos años. Dice que el universo está ordenado por la razón, el lógos, y que el sabio vive de acuerdo con la naturaleza. En Roma ha tenido grandes seguidores: Séneca, que fue maestro de Nerón y murió por orden suya, y mi maestro Musonio, desterrado varias veces. Es una filosofía para tiempos difíciles.']],
 quiz:{q:'Según Epicteto, ¿qué depende de nosotros?',a:['Nuestros juicios, deseos y aversiones','Nuestra salud, nuestros bienes y nuestra fama','El destino que nos marcan los dioses'],ko:'No. Para Epicteto solo dependen de nosotros los juicios, los deseos y las aversiones; el cuerpo, los bienes y la fama no.'}},

{id:'musonio',name:'Gayo Musonio Rufo',title:'Filósofo estoico',glyph:'M',look:Object.assign({},TOGA,{beard:true,hair:'#8d8a85',beardC:'#9a968e'}),
 cat:'Filosofía',lesson:'La filosofía también es para las mujeres',where:'En el pórtico de Pompeyo, en el Campo de Marte',
 summary:'Musonio Rufo (c. 25-c. 100), caballero etrusco y filósofo estoico, fue desterrado por Nerón a la isla de Gíaros y otra vez por Vespasiano; Tito lo hizo volver. Enseñaba una filosofía práctica: comida sencilla, trabajo, sobriedad. Sostenía que hombres y mujeres tienen la misma capacidad para la virtud y que las hijas deben estudiar filosofía como los hijos.',
 intro:'Salud. Soy Gayo Musonio Rufo. Nerón me desterró a Gíaros, una roca sin agua en el Egeo; Vespasiano me echó otra vez con los demás filósofos. Ahora, con Tito, he vuelto. A mi edad prefiero enseñar paseando bajo estos pórticos, entre los plátanos, a ver si alguno de estos jóvenes quiere ser mejor y no solo más rico.',
 topics:[
  ['¿Deben estudiar filosofía las mujeres?','¿Por qué no? Los dioses dieron a las mujeres la misma razón que a los hombres, los mismos sentidos, el mismo deseo natural de la virtud. Una mujer filósofa será mejor administradora de su casa, más justa con los esclavos, más valiente ante la desgracia, mejor madre. Por eso digo que a las hijas hay que educarlas igual que a los hijos.'],
  ['¿Qué es lo más importante en la filosofía?','La práctica. De nada sirve saber qué es la templanza si comes como un glotón. Por eso recomiendo comida sencilla, sin carne si es posible, dormir en el suelo de vez en cuando, trabajar con las manos, soportar el frío y el calor. La virtud es como la medicina o la música: no basta con conocer la teoría, hay que ejercitarse.'],
  ['¿Cómo era el destierro?','En Gíaros no había nada, ni agua. Pero me visitaba gente de toda Grecia para hablar de filosofía, y una vez encontré una fuente que nadie conocía. El destierro quita la patria, no la virtud; el mundo entero es la patria del sabio. Lo que de verdad hace daño no es el destierro, sino el miedo al destierro.']],
 quiz:{q:'¿Qué defendía Musonio Rufo sobre la educación de las mujeres?',a:['Que las hijas debían estudiar filosofía como los hijos, porque tienen la misma capacidad para la virtud','Que las mujeres solo debían aprender a tejer','Que solo las sacerdotisas podían estudiar'],ko:'No. Musonio sostenía que hombres y mujeres tienen la misma razón y capacidad para la virtud, y que las hijas debían estudiar filosofía igual que los hijos.'}},

{id:'frontino',name:'Sexto Julio Frontino',title:'Ingeniero, antiguo gobernador de Britania',glyph:'F',look:Object.assign({},TOGA,{hair:'#6b6058'}),
 cat:'Ciencia',lesson:'Los acueductos de Roma',where:'Bajo los arcos del Acueducto Claudio, en el Celio',
 summary:'Roma recibía agua por nueve acueductos en el 80. El Aqua Claudia, terminado por Claudio en el 52, traía agua desde casi setenta kilómetros por canales con una pendiente mínima, y en su último tramo cruzaba el valle sobre grandes arcos; Nerón la prolongó hasta el Celio y el Palatino. Frontino, que fue curator aquarum en el 97, describió el sistema en su tratado Sobre los acueductos de Roma.',
 intro:'Salud. Sexto Julio Frontino. He gobernado Britania y combatido a los siluros en sus montañas; ahora he vuelto a Roma. Me interesan las cosas que funcionan, y pocas funcionan tan bien como esto que tienes encima: el Acueducto Claudio. Escucha: dentro del canal corre agua que ha bajado más de sesenta kilómetros desde los montes.',
 topics:[
  ['¿Cómo llega el agua a Roma?','Por gravedad, nada más. Se capta en manantiales de los montes y se lleva por un canal de piedra cubierto, el specus, con una pendiente muy pequeña. Casi todo el recorrido va bajo tierra; solo cuando hay que cruzar un valle se levanta sobre arcos como estos. Al llegar, el agua va a depósitos, y de allí, por tuberías de plomo, a fuentes, termas y casas.'],
  ['¿Cuántos acueductos tiene Roma?','Nueve. El más antiguo, el Aqua Appia, lo construyó Apio Claudio hace casi cuatrocientos años, el mismo de la Vía Apia. Luego el Anio Vetus, el Marcia, que trae la mejor agua, fría y limpia, el Tepula, el Julia, el Virgo de Agripa, el Alsietina, que solo vale para regar, y este Claudia con el Anio Novus. Compárame esta obra con las pirámides ociosas de Egipto o con las obras inútiles y famosas de los griegos.'],
  ['¿Quién se cuida de todo esto?','Un curator aquarum, un senador, con cientos de esclavos públicos: fontaneros, vigilantes, albañiles. Su peor enemigo son los ladrones de agua: gente que pincha la tubería pública para regar su huerto o llenar su baño, a veces sobornando a los fontaneros. Algún día me gustaría poner orden en eso.']],
 quiz:{q:'¿Cómo llegaba el agua de los acueductos a Roma?',a:['Por gravedad, con una pendiente muy pequeña, casi siempre bajo tierra','Bombeada por grandes ruedas movidas por esclavos','En carros cisterna desde el Tíber'],ko:'No. El agua bajaba por gravedad desde los manantiales por un canal con una pendiente mínima; solo los valles se cruzaban sobre arcos.'}},

{id:'plinio',name:'Plinio el Joven',title:'Estudiante de retórica, de 18 años',glyph:'P',look:Object.assign({},TOGA,{hair:'#3b2a1e',scale:0.97}),
 cat:'Historia',lesson:'La erupción del Vesubio',where:'En el Foro de Augusto',
 summary:'En el 79, el Vesubio entró en erupción y sepultó Pompeya, Herculano y Estabia. Plinio el Viejo, almirante de la flota de Miseno y autor de la Historia natural, murió al intentar rescatar a los habitantes de la costa. Su sobrino, Plinio el Joven, que lo vio todo desde Miseno con 17 años, lo contó después en dos cartas a Tácito: la primera descripción detallada de una erupción volcánica.',
 intro:'Salud. Soy Gayo Plinio Cecilio Segundo, sobrino e hijo adoptivo de Plinio el Viejo. Estudio retórica con Quintiliano. El año pasado mi tío murió en la erupción del Vesubio, y yo lo vi todo desde Miseno, al otro lado del golfo. A veces todavía sueño con aquella nube.',
 topics:[
  ['¿Qué viste aquel día?','Hacia la hora séptima mi madre señaló una nube enorme sobre un monte, al otro lado del golfo. Tenía la forma de un pino: un tronco altísimo que se abría en ramas. Unas veces blanca, otras sucia, según cargara tierra o ceniza. Al día siguiente la tierra temblaba tanto que los carros se movían solos. Luego cayó una oscuridad como la de una habitación cerrada con la lámpara apagada. Se oían los gritos de mujeres y niños.'],
  ['¿Cómo murió tu tío?','Era almirante de la flota de Miseno. Al ver la nube quiso acercarse para estudiarla, como buen naturalista; luego recibió el mensaje de una mujer que pedía ayuda y convirtió la expedición en un rescate. Navegó hacia el peligro mientras todos huían. En Estabia, al tercer día, lo encontraron muerto en la playa, entero, como dormido: le faltó el aire. Había escrito treinta y siete libros de Historia natural.'],
  ['¿Qué ha pasado con Pompeya?','Ha desaparecido bajo la ceniza, igual que Herculano y Estabia. El emperador Tito fue a Campania, nombró comisionados para la reconstrucción y destinó los bienes de los muertos sin herederos a ayudar a los supervivientes. Pero esas ciudades no se van a reconstruir: están bajo varios metros de piedra pómez. Quizá algún día alguien las desentierre.']],
 quiz:{q:'¿Cómo murió Plinio el Viejo?',a:['Al intentar rescatar con la flota a los habitantes de la costa durante la erupción del Vesubio','En una batalla contra los partos','Envenenado por orden de Nerón'],ko:'No. Plinio el Viejo, almirante de la flota de Miseno, murió en Estabia durante la erupción del Vesubio del 79, cuando intentaba rescatar a los habitantes de la costa.'}},

{id:'tacito',name:'Publio Cornelio Tácito',title:'Joven senador',glyph:'T',look:Object.assign({},TOGA,{hair:'#2b1f17'}),
 cat:'Política',lesson:'El Senado y la carrera de los honores',where:'Ante la Curia Julia, en el Foro',
 summary:'En la Roma imperial el Senado seguía existiendo, con unos 600 miembros, pero el poder real era del emperador (princeps). La carrera de los honores (cursus honorum) seguía un orden fijo: cuestor, edil o tribuno de la plebe, pretor y cónsul, con edades mínimas. Tácito, que hizo carrera bajo los Flavios, escribió después los Anales y las Historias, con una visión amarga del poder imperial.',
 intro:'Salud. Publio Cornelio Tácito. Soy joven para estar ante la Curia, ya lo sé: tengo unos veinticuatro años. Me casé hace poco con la hija de Gneo Julio Agrícola, que ahora gobierna Britania, y Vespasiano me abrió la carrera senatorial. Algún día escribiré la historia de estos tiempos. Si me atrevo.',
 topics:[
  ['¿Qué es el cursus honorum?','La carrera de los honores. Primero, cargos menores y servicio como tribuno en una legión. Luego, hacia los veinticinco años, cuestor: administras dinero público y entras en el Senado. Después edil o tribuno de la plebe; hacia los treinta, pretor, que juzga; y al final, si el emperador quiere, cónsul. Cada cargo dura un año y se comparte con colegas. Y después, gobernar una provincia o mandar un ejército.'],
  ['¿Qué poder tiene el Senado?','Mucho de nombre, poco de hecho. Seiscientos senadores con túnica de franja púrpura, que votan decretos, juzgan a los suyos y gobiernan algunas provincias. Pero desde Augusto el que manda es el príncipe: tiene los ejércitos, el dinero y la última palabra. Hemos aprendido a callar y a adular. Con un buen príncipe, como Tito, la cosa se soporta. Con uno malo, como Nerón, cada sesión podía ser la última.'],
  ['¿Por qué quieres escribir historia?','Porque alguien tiene que contar sin ira ni parcialidad lo que pasó: el año de los cuatro emperadores, cuando se mataron Galba, Otón y Vitelio y Roma ardió en guerra civil hasta que llegó Vespasiano. Los historiadores de la corte mienten por miedo o por odio. Yo esperaré a que haya un tiempo feliz en que se pueda pensar lo que se quiera y decir lo que se piensa.']],
 quiz:{q:'¿Qué cargo daba entrada al Senado en la carrera de los honores?',a:['La cuestura','El consulado','La censura'],ko:'No. El primer cargo de la carrera senatorial era la cuestura, que daba entrada en el Senado; el consulado era la cima.'}},

{id:'dion',name:'Dion de Prusa',title:'Orador y filósofo griego',glyph:'Δ',look:{chiton:'#efe8da',himation:'#4f6a7d',beard:true,hair:'#4a3a2c'},
 cat:'Cultura',lesson:'Los griegos en Roma',where:'Ante el Teatro de Pompeyo, en el Campo de Marte',
 summary:'Roma estaba llena de griegos: maestros, médicos, filósofos, esclavos, comerciantes. La élite romana hablaba griego, leía a Homero y a Platón y enviaba a sus hijos a estudiar a Atenas o a Rodas. Dion de Prusa (c. 40-c. 115), llamado Crisóstomo («boca de oro»), fue uno de los oradores griegos más famosos; bajo Domiciano sería desterrado y vagaría años por el imperio como un filósofo cínico.',
 intro:'Khaíre, extranjero, o salve, si lo prefieres. Soy Dion, de Prusa, en Bitinia. Los romanos me llaman orador; mis amigos, filósofo. Roma conquistó Grecia, dicen, pero Grecia conquistó a su fiero vencedor: aquí todo el que es alguien habla griego, tiene un médico griego y un maestro griego para sus hijos.',
 topics:[
  ['¿Por qué hay tantos griegos en Roma?','Porque aquí están el poder y el dinero, y nosotros tenemos lo que Roma admira: la filosofía, la retórica, la medicina, la escultura. Horacio lo dijo: Grecia, conquistada, conquistó a su fiero vencedor y llevó las artes al rústico Lacio. Pero también hay recelo; hay poetas que se quejan de que Roma se ha vuelto una ciudad griega. Y muchos griegos han llegado aquí como esclavos.'],
  ['¿Has estado en Atenas?','Muchas veces. Atenas es hoy una ciudad pequeña bajo Roma, pero sigue siendo la escuela de Grecia: la Academia, el Liceo, la Stoa. Los jóvenes romanos ricos van allí a estudiar, como hizo Cicerón. Se sienta uno en el teatro de Dioniso y piensa en Eurípides. Aún se discute en el Ágora como en tiempos de Sócrates, aunque las decisiones se tomen aquí.'],
  ['¿Qué es un sofista hoy?','Ya no es un insulto, como en tiempos de Platón. Somos conferenciantes: hablamos en teatros y en las cortes, improvisamos sobre cualquier tema, elogiamos ciudades, aconsejamos a reyes. A veces es pura pirotecnia. Yo procuro que mis discursos sirvan para algo: hablar de la concordia entre ciudades, de la virtud del gobernante, de la vida sencilla del campo.']],
 quiz:{q:'¿Qué significaba la frase de Horacio sobre Grecia y Roma?',a:['Que Grecia, conquistada por Roma, conquistó a su vencedor con su cultura','Que Roma destruyó toda la cultura griega','Que los griegos nunca aprendieron latín'],ko:'No. Horacio escribió que Grecia, conquistada, conquistó a su fiero vencedor: Roma adoptó la cultura griega.'}},

{id:'sulpicia',name:'Sulpicia',title:'Poetisa',glyph:'S',look:{female:true,chiton:'#efe2d6',himation:'#8a3f5e',hair:'#3b2a1e'},
 cat:'Sociedad',lesson:'Las mujeres romanas',where:'En los jardines del Aventino',
 summary:'Las romanas libres no votaban ni ocupaban cargos, pero tenían más libertad que las atenienses: comían con sus maridos, salían a la calle, asistían a los espectáculos, podían heredar y administrar bienes, y desde Augusto las madres de tres hijos quedaban libres de la tutela. Sulpicia, citada por Marcial, escribía poemas de amor a su marido Caleno, algo raro en una literatura escrita casi solo por hombres.',
 intro:'Salud, forastero. Soy Sulpicia. Escribo versos: sí, una mujer, y casada, y a mi propio marido, Caleno. Marcial dice que todas las mujeres deberían leerme. Los hombres de Roma se escandalizan de que una matrona hable de amor, pero yo no escribo nada de lo que me tenga que avergonzar.',
 topics:[
  ['¿Qué pueden hacer las mujeres en Roma?','Más que en Grecia, me dicen los griegos. Comemos a la mesa con nuestros maridos, salimos a la calle, vamos a las termas, al teatro, al circo. Podemos heredar, tener bienes propios y administrarlos. Si tengo tres hijos, quedo libre de tutor, por una ley de Augusto. Lo que no podemos es votar, ni hablar en el Senado, ni ser magistradas. Y algunas, como Agripina, la madre de Nerón, mandaron más que muchos cónsules.'],
  ['¿Cómo es un matrimonio romano?','Basta con la voluntad de los dos de vivir como marido y mujer, y el consentimiento de los padres. Hay boda, claro: el velo color llama, el pastel de espelta, la mano derecha en la mano derecha, el cortejo a la casa del novio. La mujer casi siempre sigue perteneciendo a su familia y conserva sus bienes. Y el divorcio es fácil: basta con decirlo. Por eso, cuando un matrimonio dura, es porque se quieren.'],
  ['¿Hay otras poetisas?','Pocas que conozcáis. Hace un siglo hubo otra Sulpicia, sobrina de Mesala, que escribió versos de amor a un tal Cerinto; se leen junto a los de Tibulo. Y las griegas tenían a Safo. Las romanas escribimos cartas, memorias, a veces discursos: Hortensia habló en el Foro contra un impuesto de los triunviros. Pero la poesía la escriben los hombres, sobre nosotras. Yo prefiero escribirla yo.']],
 quiz:{q:'¿Qué derecho obtenían, por una ley de Augusto, las madres de tres hijos?',a:['Quedar libres de la tutela de un hombre','Votar en las asambleas','Ser elegidas senadoras'],ko:'No. Por las leyes de Augusto (el derecho de los tres hijos), la mujer libre con tres hijos quedaba libre de tutela y podía administrar sus bienes.'}},

{id:'rabirio',name:'Rabirio',title:'Arquitecto',glyph:'R',look:{short:true,chiton:'#c9b48b',hair:'#5b4532',beard:true},
 cat:'Ciencia',lesson:'Hormigón, arcos y bóvedas',where:'En las obras del Palatino',
 summary:'Los romanos revolucionaron la arquitectura con el hormigón (opus caementicium): cal, arena volcánica (pozzolana), agua y piedras, que fraguaba incluso bajo el agua. Combinado con el arco y la bóveda, permitió cubrir grandes espacios: termas, anfiteatros, palacios, acueductos. Rabirio fue el arquitecto de Domiciano que construyó el gran palacio del Palatino, terminado hacia el 92.',
 intro:'Cuidado con el andamio, que eso es cal viva. Soy Rabirio, arquitecto. Aquí, en el Palatino, estamos empezando algo grande: el hermano del emperador, Domiciano, quiere un palacio que haga parecer pequeña la Casa Dorada de Nerón. Salones con bóvedas tan altas que parecerá que el cielo está dentro.',
 topics:[
  ['¿Cuál es vuestro secreto?','El hormigón. Mezclamos cal con el polvo de Puteoli, la arena volcánica de Campania, añadimos agua y trozos de piedra o ladrillo, y lo vertemos entre dos muros de ladrillo como si fueran un molde. Fragua como la roca, incluso bajo el agua: así hacemos los puertos. Y no necesitas grandes bloques de mármol ni canteros griegos: basta con esclavos, cal y paciencia.'],
  ['¿Cómo se cubre un espacio tan grande?','Con el arco, que reparte el peso hacia los lados, y con la bóveda, que es un arco que se prolonga, o que gira sobre sí mismo, como la cúpula. Los griegos solo sabían poner vigas de piedra sobre columnas, y por eso sus templos están llenos de columnas. Nosotros podemos levantar una sala de cien pies sin un solo apoyo en medio. Mira el Anfiteatro Flavio: es todo arcos y bóvedas, por dentro y por fuera.'],
  ['¿Qué fue la Casa Dorada?','El palacio de Nerón después del incendio del 64: ocupaba medio centro de Roma, con un lago artificial donde hoy está el anfiteatro, viñas, bosques y una sala de banquetes que giraba como el cielo. Sus arquitectos, Severo y Céler, eran genios. Pero los Flavios han devuelto el terreno al pueblo: sobre el lago, el anfiteatro; sobre parte del palacio, las termas de Tito. Nerón decía que por fin vivía como un ser humano. Lo pagó Roma.']],
 quiz:{q:'¿Qué material permitió a los romanos construir grandes bóvedas y puertos?',a:['El hormigón hecho con cal y arena volcánica','El hierro fundido','El mármol, en grandes bloques'],ko:'No. El gran invento fue el hormigón (opus caementicium), de cal y arena volcánica (pozzolana), que fraguaba incluso bajo el agua.'}},

{id:'atrecto',name:'Atrecto',title:'Librero del Argileto',glyph:'A',look:{chiton:'#e2d6c0',himation:'#4a5a3a',beard:true,hair:'#5b4532'},mythBrowser:true,
 cat:'Cultura',lesson:'Libros y lectura en Roma',where:'En su tienda del Argileto, junto al Foro',
 summary:'En la Roma del siglo I había librerías en el Argileto y en otras calles del centro, con los títulos anunciados en las columnas de la entrada. Los libros eran rollos de papiro copiados por esclavos; empezaban a aparecer los primeros códices de pergamino. Había bibliotecas públicas: la del Atrio de la Libertad, la del templo de Apolo en el Palatino, la del Pórtico de Octavia y la del Templo de la Paz.',
 intro:'Pasa, pasa. Atrecto, librero, para servirte. ¿Ves las columnas de la entrada? Ahí anuncio lo que tengo: Virgilio, Ovidio, Livio, y Marcial, que es el que más se vende aunque él diga que no ve un as. Y si no sabes qué leer, te cuento yo las viejas historias de Roma, y las de los griegos.',
 topics:[
  ['¿Cómo se hace un libro?','En el taller de atrás tengo doce copistas, casi todos esclavos griegos. Uno dicta y los demás copian a la vez en rollos de papiro egipcio. En un día salen varias copias de un libro corto. Ahora también vendo libros pequeños de pergamino, con las hojas cosidas: caben en una mano y puedes leerlos de viaje. Marcial los recomienda. Dicen que es una moda, que no durará.'],
  ['¿Hay bibliotecas públicas?','Sí. César quería una, y la hizo Asinio Polión en el Atrio de la Libertad. Augusto puso dos, una griega y una latina, junto al templo de Apolo en el Palatino, y otra en el Pórtico de Octavia. Y Vespasiano, otra en su Templo de la Paz. Cualquiera puede entrar a leer. Pero los libros que quieres de verdad, los compras aquí.'],
  ['¿Qué lee la gente?','Los niños aprenden con Virgilio, como antes los griegos con Homero. Los mayores leen a Cicerón, a Livio, que contó toda la historia de Roma en ciento cuarenta y dos libros, a Ovidio y sus Metamorfosis, a Séneca. Y en las cenas se recitan poemas nuevos. Mucha gente no sabe leer, claro, pero escucha: en los foros, en las termas, en las lecturas públicas.']],
 quiz:{q:'¿Qué formato de libro empezaba a aparecer en Roma en el siglo I d.C., junto al rollo de papiro?',a:['El códice, con hojas de pergamino cosidas','El libro impreso','La tablilla de arcilla'],ko:'No. Junto al rollo empezó a usarse el códice, con hojas de pergamino cosidas; Marcial lo recomienda para leer de viaje.'}},

{id:'prisco',name:'Prisco',title:'Gladiador liberado por Tito',glyph:'P',look:{short:true,soldier:'nospear',chiton:'#a8392b',hair:'#2a1e16'},
 cat:'Sociedad',lesson:'Los gladiadores',where:'En la arena del Anfiteatro Flavio (entra por la puerta oeste)',
 summary:'Los gladiadores eran casi siempre esclavos, prisioneros o condenados, aunque también había hombres libres que se contrataban. Se entrenaban en escuelas (ludi) y luchaban por parejas con armas distintas: el mirmilón con casco y escudo grande, el reciario con red y tridente, el tracio con escudo pequeño y espada curva. No todos los combates acababan en muerte: el editor y el público podían conceder la vida, y el gladiador que destacaba podía recibir el rudis, la espada de madera de la libertad.',
 intro:'Mírame bien, forastero: soy Prisco, y desde hace unos días soy libre. Tengo la espada de madera, el rudis. Luché contra Vero en la inauguración del anfiteatro y ninguno de los dos pudo vencer al otro. El emperador nos dio la libertad a los dos. Marcial ha escrito un poema. Yo no sé leer, pero me lo han recitado.',
 topics:[
  ['¿Cómo fue el combate?','Duró muchísimo. El público gritaba nuestros nombres y pedía la libertad para los dos. Tito había puesto una regla: se lucha hasta que uno levante el dedo para rendirse. Al final, agotados, los dos levantamos el dedo a la vez. El César nos mandó a los dos la palma y el rudis. Dicen que es la mejor pelea de los cien días.'],
  ['¿Cómo se llega a ser gladiador?','A mí me compraron en un mercado de esclavos; a otros los condenan por un delito. Hay hombres libres que se venden por deudas o por gloria: juran dejarse quemar, azotar y matar con el hierro. En la escuela comes bien, te curan los médicos, entrenas cada día contra un poste de madera. Cada uno tiene su armadura: yo soy mirmilón, con casco y escudo grande. Mi rival favorito es el tracio.'],
  ['¿Se muere siempre?','No tanto como cree la gente. Un gladiador cuesta mucho dinero al que lo entrena, y un buen combate vale más que un muerto. Si caes y luchaste bien, el público agita los pañuelos y el editor te concede la vida. Si luchaste mal… Muchos mueren jóvenes, sí. Pero algunos llegan a viejos y entrenan a otros. Y las mujeres de Roma nos adoran.']],
 quiz:{q:'¿Qué recibía un gladiador como símbolo de su libertad?',a:['El rudis, una espada de madera','Una corona de laurel de oro','Un anillo de hierro'],ko:'No. El símbolo de la liberación del gladiador era el rudis, una espada de madera; Prisco y Vero lo recibieron de Tito.'}},

{id:'cornelia',name:'Cornelia',title:'Virgen vestal',glyph:'C',look:{female:true,chiton:'#f4efe4',himation:'#f4efe4',veil:'#f4efe4',hair:'#3a281c'},
 cat:'Religión',lesson:'Las vestales',where:'En la Casa de las Vestales, junto al Foro',
 summary:'Las seis vestales, elegidas de niñas entre familias patricias, servían treinta años a Vesta, diosa del hogar, guardando el fuego sagrado que nunca debía apagarse en su templo redondo del Foro, y objetos sagrados como el Paladio. Tenían privilegios extraordinarios: no estaban bajo tutela, tenían asientos de honor y un lictor. Si perdían la virginidad, eran enterradas vivas.',
 intro:'Salud. Soy Cornelia, sacerdotisa de Vesta. Entré en este atrio con diez años, y llevo aquí la mitad de mi vida. Guardamos el fuego de Roma: mientras arda en el templo redondo, Roma vivirá. Si un día se apaga, la vestal culpable será azotada por el pontífice máximo, que es el propio emperador.',
 topics:[
  ['¿Quiénes son las vestales?','Somos seis. El pontífice máximo nos elige de niñas, entre los seis y los diez años, en familias de buena sangre, con padre y madre vivos. Servimos treinta años: diez aprendiendo, diez sirviendo y diez enseñando. Después podemos salir y casarnos, aunque casi ninguna lo hace. Guardamos el fuego, preparamos la harina sagrada para los sacrificios y custodiamos el Paladio, la imagen de Palas que Eneas trajo de Troya.'],
  ['¿Qué privilegios tenéis?','Más que cualquier mujer de Roma. No tenemos tutor, podemos hacer testamento, un lictor nos abre paso por la calle, tenemos el mejor sitio en los espectáculos. Si un condenado a muerte se cruza con una vestal, queda libre. Nuestra palabra vale sin juramento. Los grandes, como César o Augusto, dejaban aquí sus testamentos.'],
  ['¿Y si una vestal falta a su voto?','Si pierde la virginidad, ha roto la paz con los dioses, y Roma corre peligro. Se la lleva en una litera cerrada, como en un funeral, hasta el Campo Maldito, junto a la puerta Colina, y se la baja a una cámara bajo tierra con una lámpara, pan, agua, leche y aceite. Y se cierra. Nadie la mata: deciden los dioses. Hace tiempo que no ocurre. Ojalá no vuelva a ocurrir.']],
 quiz:{q:'¿Cuál era la tarea principal de las vestales?',a:['Guardar el fuego sagrado de Vesta, que nunca debía apagarse','Dirigir los juegos del circo','Interpretar el vuelo de las aves'],ko:'No. Las vestales guardaban el fuego sagrado del templo de Vesta, símbolo de la continuidad de Roma, además de otros objetos sagrados.'}},

{id:'hermeros',name:'Gayo Pompeyo Hermeros',title:'Liberto enriquecido',glyph:'H',look:{chiton:'#e6d2a8',toga:true,himation:'#efe6d0',hair:'#2b1f17',scale:1.05},
 cat:'Sociedad',lesson:'Esclavos y libertos',where:'En el Foro, cerca del Templo de Saturno',
 summary:'Roma era una sociedad esclavista: quizá uno de cada cuatro o cinco habitantes de Italia era esclavo. Pero los romanos liberaban con frecuencia a sus esclavos (manumisión), y el liberto de un ciudadano se convertía en ciudadano, aunque debía respeto y servicios a su antiguo amo, ahora su patrono. Algunos libertos se enriquecieron enormemente con el comercio; sus hijos ya eran ciudadanos de pleno derecho.',
 intro:'Mira bien este anillo de oro, forastero. Lo llevo yo, Hermeros, que llegué a Roma con un cartel colgado al cuello en el mercado de esclavos. Mi amo me liberó, aprendí a comerciar con vino y aceite, y ahora tengo barcos, tiendas y esclavos propios. Mi hijo será caballero, ya lo verás.',
 topics:[
  ['¿Cómo se libera a un esclavo?','De varias maneras: ante un magistrado, que te toca con una vara; en el testamento del amo, que es lo más común; o inscribiéndote en el censo como ciudadano. Muchos amos liberan a sus esclavos de confianza, o les dejan comprar su libertad con sus ahorros, el peculio. Te pones el gorro de liberto y ya eres ciudadano romano. Bueno, casi: no puedes ser magistrado. Pero tus hijos sí.'],
  ['¿Qué le debes a tu antiguo amo?','Ahora es mi patrono. Le debo respeto, algunos días de trabajo al año, y si muero sin hijos, parte de mi herencia es suya. Voy a saludarle por las mañanas como cualquier cliente. A cambio me protege, me presta dinero si lo necesito y me defiende en los tribunales. Y llevo su nombre: Gayo Pompeyo Hermeros. Somos como una familia, aunque yo sepa que él me podía haber vendido.'],
  ['¿Cómo te hiciste rico?','Trabajando mientras los nobles hacían discursos. Los senadores no pueden tener barcos grandes de comercio: queda feo. Así que los negocios los hacemos los libertos. Mandé cinco barcos de vino a Roma y se hundieron todos: treinta millones de sestercios al fondo del mar. Construí otros más grandes y mejores, y con un solo viaje gané diez millones. Hay quien se ríe de cómo hablo. Que se rían: yo tengo más dinero que ellos.']],
 quiz:{q:'¿Qué pasaba con el esclavo de un ciudadano romano cuando era liberado?',a:['Se convertía en ciudadano romano, aunque debía respeto y servicios a su patrono','Seguía siendo esclavo de la ciudad','Tenía que abandonar Italia'],ko:'No. Con la manumisión, el esclavo de un ciudadano se hacía ciudadano (con algunas limitaciones) y su antiguo amo pasaba a ser su patrono.'}},

{id:'cliente',name:'Lucio Fabio',title:'Cliente en la salutatio',glyph:'L',look:Object.assign({},TOGA,{beard:true,hair:'#6b5a40'}),
 cat:'Sociedad',lesson:'Patronos y clientes',where:'A la puerta de una domus del Celio',
 summary:'La sociedad romana se basaba en relaciones de patronazgo: el patrono, rico e influyente, protegía a sus clientes, y estos le acompañaban, le apoyaban en las elecciones y le saludaban cada mañana en la salutatio, vestidos con toga. A cambio recibían la espórtula, una pequeña cantidad de dinero o comida, ayuda en los juicios y favores. Marcial y Juvenal se quejan de lo humillante de esta rutina.',
 intro:'Shh, no hables alto: estamos esperando a que abran la puerta. Soy Lucio Fabio, cliente del ilustre senador que vive aquí. Llevo desde antes del alba con la toga puesta en esta cola. Cuando abran, entraremos por orden de importancia y le saludaremos, y si hay suerte me invitará a cenar. Si no, la espórtula: seis sestercios y cuarto.',
 topics:[
  ['¿Qué es un cliente?','Alguien que depende de un hombre poderoso, su patrono. Cada mañana vengo a saludarle a su casa con la toga, le acompaño al foro para que se vea cuánta gente le sigue, aplaudo sus discursos, le voto si se presenta a algo. A cambio, me da la espórtula, me defiende si tengo un pleito, me presta dinero, me recomienda. Así funciona Roma de arriba abajo: hasta mi patrono es cliente de alguien más poderoso, y todos, del emperador.'],
  ['¿Cómo es una domus por dentro?','Desde aquí verás el vestíbulo y, al fondo, el atrio: una sala alta con un agujero en el techo, el compluvio, y un estanque debajo, el impluvio, que recoge la lluvia. Alrededor, las habitaciones; al fondo, el tablino, donde el señor recibe, con las máscaras de cera de sus antepasados en armarios. Detrás, el peristilo, un jardín con columnas. Las casas de los ricos dan la espalda a la calle: hacia fuera, solo tiendas y muros.'],
  ['¿Vale la pena?','Te diré lo que dice Marcial: después de una mañana de pie, cien cuadrantes. Hay patronos que cenan ostras y dan a sus clientes un vino malo en el mismo banquete. Pero en una ciudad de un millón de almas, sin patrono no eres nadie. ¿Quién te va a ayudar si el casero te echa o si un rico te pega en la calle? La toga y la paciencia son el precio.']],
 quiz:{q:'¿Qué era la salutatio?',a:['La visita matinal de los clientes para saludar a su patrono en su casa','Un saludo militar ante el emperador','La fiesta de la diosa Salus'],ko:'No. La salutatio era la visita que los clientes hacían cada mañana, vestidos con toga, a la casa de su patrono, que les daba a cambio la espórtula.'}},

{id:'pretoriano',name:'Marco Valerio Pudente',title:'Soldado de la guardia pretoriana',glyph:'V',look:{soldier:true,chiton:'#a8392b',hair:'#2a1e16'},
 cat:'Historia',lesson:'El ejército romano',where:'En la subida al Palatino',
 summary:'El ejército imperial tenía unas 28 legiones de unos 5.000 ciudadanos cada una, que servían 20 o 25 años, y un número parecido de tropas auxiliares de provinciales, que recibían la ciudadanía al licenciarse. En Roma estaban la guardia pretoriana, que protegía al emperador y cobraba mucho más, las cohortes urbanas y los vigiles. Los pretorianos llegaron a decidir quién era emperador.',
 intro:'Alto ahí. Ah, un forastero. Marco Valerio Pudente, de la guardia pretoriana. Protegemos al emperador y a su familia, aquí en el Palatino. Nueve cohortes, con su campamento junto a la puerta Viminal. Cobramos tres veces más que un legionario y servimos dieciséis años, no veinticinco. No te quejes si te miro mal: es mi oficio.',
 topics:[
  ['¿Cómo es una legión?','Unos cinco mil ciudadanos de infantería pesada, divididos en diez cohortes, y cada cohorte en centurias de ochenta hombres al mando de un centurión. Cada legionario lleva su coraza de láminas, el casco, el escudo largo, dos jabalinas, la espada corta y una pala para cavar: cada noche se construye un campamento. Los auxiliares, que no son ciudadanos, ponen la caballería, los arqueros y los honderos. Al licenciarse reciben la ciudadanía.'],
  ['¿Qué poder tenéis los pretorianos?','Más del que deberíamos. Cuando mataron a Calígula, unos pretorianos encontraron a su tío Claudio escondido tras una cortina y lo hicieron emperador. Después, cada nuevo emperador nos ha pagado un donativo al subir al trono. En el año de los cuatro emperadores se vendió y se compró el imperio. Ahora, con Tito, que fue nuestro prefecto, todo está tranquilo.'],
  ['¿Dónde está la frontera?','Lejos: el Rin y el Danubio al norte, el Éufrates al este, el desierto al sur, el océano al oeste. Y en Britania, el gobernador Agrícola avanza hacia el norte, hacia Caledonia. En la frontera hay campamentos de piedra, calzadas y torres de vigilancia. Desde aquí, la guerra parece un desfile: los triunfos, el botín, los prisioneros en el anfiteatro.']],
 quiz:{q:'¿Qué recibían los soldados auxiliares al terminar su servicio?',a:['La ciudadanía romana','Un puesto en el Senado','Una casa en Roma'],ko:'No. Los auxiliares, que no eran ciudadanos, recibían la ciudadanía romana al licenciarse, como muestran los diplomas militares de bronce.'}},

{id:'auriga',name:'Félix',title:'Auriga de la facción de los verdes',glyph:'F',look:{short:true,chiton:'#3f7a3a',hair:'#3b2a1e'},
 cat:'Sociedad',lesson:'Las carreras del Circo Máximo',where:'En el Circo Máximo, junto a las cárceres (las puertas de salida)',
 summary:'El Circo Máximo, entre el Palatino y el Aventino, era el mayor edificio de espectáculos de Roma: unos 600 metros de largo y capacidad para más de 150.000 espectadores. Las carreras de carros (cuadrigas de cuatro caballos, bigas de dos) daban siete vueltas alrededor de la espina. Los aurigas corrían para cuatro facciones, verdes, azules, rojos y blancos, que tenían seguidores apasionados. Los mejores aurigas, casi siempre esclavos o libertos, ganaban fortunas.',
 intro:'¡Eh, forastero! ¿Verde o azul? Elige bien, que en Roma eso importa más que la política. Soy Félix, auriga de los verdes. Esta tarde corro. Siete vueltas alrededor de la espina, rozando las metas en cada curva: si te abres pierdes; si te cierras demasiado, el carro vuela en pedazos.',
 topics:[
  ['¿Cómo es una carrera?','Doce carros salen de las cárceres, esas puertas del extremo oeste, cuando el magistrado deja caer un pañuelo blanco. Siete vueltas, unas cinco millas. En la espina, unos delfines de bronce se bajan para contar las vueltas. Las curvas son lo peligroso: llevo las riendas atadas a la cintura para dirigir con el cuerpo, y un cuchillo para cortarlas si vuelco. Si no, te arrastran los caballos.'],
  ['¿Qué son las facciones?','Cuatro empresas que tienen caballos, carros, aurigas, mozos y médicos: los verdes, los azules, los rojos y los blancos. La gente es de una facción como de una familia. Hay quien echa incienso a la pira del auriga muerto y quien entierra tablillas de maldición contra el rival. Nerón era de los verdes. De qué color es el emperador ahora, eso no se pregunta.'],
  ['¿Se gana mucho?','Si ganas, muchísimo. Los mejores aurigas acaban con millones de sestercios y estatuas en su honor. Yo soy liberto y tengo una casa con tres pisos. Pero en la curva no hay dinero que valga: he visto morir a compañeros pisoteados delante de cien mil personas que gritaban mi nombre. Y aun así, no hay nada como ese grito.']],
 quiz:{q:'¿Cuántas vueltas daban los carros en una carrera del Circo Máximo?',a:['Siete','Tres','Doce'],ko:'No. La carrera habitual era de siete vueltas alrededor de la espina; se contaban con huevos y delfines de bronce.'}},

{id:'mercader',name:'Tiberio Claudio Eutiques',title:'Comerciante de grano del Emporio',glyph:'E',look:{chiton:'#d8c7a3',himation:'#6b5a3a',beard:true,hair:'#3a2a20'},
 cat:'Sociedad',lesson:'La annona: pan para Roma',where:'En el Emporio, a orillas del Tíber, bajo el Aventino',
 summary:'Roma, con cerca de un millón de habitantes, dependía del trigo importado de Egipto, África y Sicilia, que llegaba a Puteoli y Ostia y subía por el Tíber hasta el Emporio. El Estado repartía trigo gratis cada mes a unos 200.000 ciudadanos, organizado por el prefecto de la annona. Juvenal resumió la política imperial en «pan y circo».',
 intro:'Cuidado con los sacos, que hay mucho trajín. Soy Tiberio Claudio Eutiques, liberto de la casa imperial, y vivo del trigo. Las barcas suben desde Ostia remolcadas por bueyes, descargamos aquí, en el Emporio, y lo llevamos a los almacenes. Roma come cada año más trigo del que produce Italia entera.',
 topics:[
  ['¿De dónde viene el trigo?','De Egipto, sobre todo: la cosecha del Nilo alimenta a Roma cuatro meses al año. Y de África, de Sicilia, de Cerdeña. Grandes barcos de grano llegan a Puteoli o al nuevo puerto de Claudio en Ostia; allí se pasa a barcas más pequeñas que suben por el Tíber. Si una flota de Alejandría se retrasa por las tormentas, el precio del pan sube y la gente se amotina en el circo.'],
  ['¿Es verdad que reparten trigo gratis?','A unos doscientos mil ciudadanos inscritos en las listas: cinco modios al mes, unos treinta y tantos kilos, lo justo para una persona. Van con su ficha al Pórtico Minucio. Empezó Gayo Graco vendiéndolo barato, Clodio lo hizo gratis y Augusto lo organizó con un prefecto de la annona. Los emperadores saben que el pueblo de Roma solo pide dos cosas, como dirá algún poeta: pan y circo.'],
  ['¿Y ese monte de cascos?','Allí, detrás de los almacenes, tiramos las ánforas de aceite de Hispania una vez vacías. El aceite empapa la arcilla y no se pueden reutilizar, así que se rompen y se apilan en orden, con cal para el olor. Al ritmo que se consume aceite en Roma, algún día será un monte de verdad. Cada ánfora lleva sellos con el nombre del productor: una montaña de contabilidad.']],
 quiz:{q:'¿De dónde venía buena parte del trigo que comía Roma?',a:['De Egipto, África y Sicilia, por mar','De los huertos de dentro de la ciudad','De Britania, por tierra'],ko:'No. Roma dependía del trigo importado por mar, sobre todo de Egipto, África y Sicilia; llegaba a Ostia o Puteoli y subía por el Tíber.'}},

{id:'termas',name:'Secundo',title:'Encargado de las Termas de Tito',glyph:'S',look:{short:true,chiton:'#d8cfb8',hair:'#5b4532',beard:true},
 cat:'Sociedad',lesson:'Las termas',where:'A la entrada de las Termas de Tito',
 summary:'Las termas eran baños públicos y centros sociales: por una entrada mínima (un cuadrante) o gratis, cualquiera podía ejercitarse en la palestra, bañarse en salas a distintas temperaturas (frigidario, tepidario, caldario), recibir masajes y charlar. El agua llegaba por los acueductos y se calentaba con hornos que mandaban aire caliente bajo el suelo (hipocausto). Tito inauguró sus termas en el 80, junto al anfiteatro.',
 intro:'Bienvenido a las termas del emperador Tito, recién inauguradas: todavía huele a cal. Soy Secundo, encargado de los baños. Pasa, que por un cuadrante tienes palestra, baños fríos, templados y calientes, y gente con la que hablar hasta la cena. Hoy, por los juegos, la entrada es gratis.',
 topics:[
  ['¿Cómo se toma un baño?','Primero, ejercicio en la palestra: pelota, pesas, lucha. Luego te untas de aceite y te lo quitas con el estrígilo. Pasas al tepidario, templado, para ir calentándote; al caldario, con el agua caliente y el aire húmedo, hasta sudar; y terminas en el frigidario, agua fría, para cerrar los poros. Después, masaje, depilación, perfumes. Y charla: aquí se cierran negocios y se cuentan chismes.'],
  ['¿Cómo se calienta el agua?','Con hornos que alimentan los esclavos día y noche con leña. El aire caliente pasa por debajo del suelo, levantado sobre pilas de ladrillos, el hipocausto, y sube por tubos dentro de las paredes. El suelo del caldario quema: hay que ir con sandalias de madera. El agua llega del acueducto a grandes depósitos, y de allí, por tuberías de plomo, a las piscinas.'],
  ['¿Se bañan juntos hombres y mujeres?','Depende de las termas y de los tiempos. Lo decente es que haya horarios separados o salas distintas: las mujeres por la mañana, los hombres por la tarde. Pero en algunos baños se mezcla todo el mundo y los moralistas se escandalizan. Séneca, que vivía encima de unos baños, se quejaba del ruido: gritos, golpes de masaje, el depilador anunciándose, el vendedor de salchichas.']],
 quiz:{q:'¿Cómo se llamaba la sala de agua caliente de unas termas romanas?',a:['Caldario','Frigidario','Peristilo'],ko:'No. El caldario era la sala caliente; el tepidario, la templada, y el frigidario, la fría.'}},

{id:'vigil',name:'Aulo Sempronio',title:'Vigil (bombero) de la Subura',glyph:'V',look:{short:true,chiton:'#8a6a3a',hair:'#2a1e16',beard:true,staff:true},
 cat:'Sociedad',lesson:'Las ínsulas y los incendios',where:'En una calle de la Subura',
 summary:'La mayoría de los romanos vivía de alquiler en ínsulas, bloques de pisos de cuatro o cinco alturas con tiendas en la planta baja. Los pisos bajos eran los mejores; arriba vivían los pobres, sin agua ni letrinas, con el peligro de derrumbes e incendios. Tras el gran incendio del 64, Nerón limitó la altura de los edificios y obligó a usar materiales menos inflamables. Augusto había creado los vigiles: siete cohortes de libertos que vigilaban de noche y apagaban los fuegos.',
 intro:'¡Apártate de ese brasero, por Vulcano! Perdona, forastero. Soy Aulo Sempronio, de la segunda cohorte de vigiles. Patrullamos la Subura de noche con cubos, hachas, esponjas y mantas mojadas. En este barrio se cocina en braseros sobre suelos de madera: cada noche hay un fuego en algún sitio. Y cuando hay uno grande…',
 topics:[
  ['¿Cómo se vive en una ínsula?','Abajo, las tiendas: panaderos, zapateros, tabernas. El primer piso es el mejor, a veces con agua corriente. Cuanto más subes, más barato y peor: habitaciones pequeñas, sin agua, sin letrina, con vasijas que se vacían por la ventana, ojo al pasar. El alquiler de un cuchitril en Roma cuesta lo que una casa entera en el campo. Y las paredes son tan finas que se derrumban: los caseros lo arreglan con un poco de yeso.'],
  ['¿Qué pasó en el gran incendio?','Hace dieciséis años, en julio, empezó un fuego en las tiendas del Circo Máximo y duró nueve días. De los catorce barrios de Roma, tres desaparecieron y siete quedaron casi destruidos. Mi padre era vigil: decía que no había forma de pararlo, que saltaba de calle en calle. Unos culparon a Nerón, que reconstruyó con su Casa Dorada; Nerón culpó a los cristianos. Desde entonces las calles son más anchas y hay pórticos de piedra. Más o menos.'],
  ['¿Quiénes son los vigiles?','Siete cohortes, unos siete mil hombres, casi todos libertos, una por cada dos barrios. Augusto nos creó después de que un político, Craso, se hiciera rico comprando casas en llamas a precio de ruina antes de apagarlas con su brigada privada. Patrullamos de noche, avisamos de los braseros mal puestos, perseguimos a los ladrones y, si hay fuego, derribamos casas para cortarle el paso. Tras unos años de servicio, nos dan la ciudadanía.']],
 quiz:{q:'¿Quiénes apagaban los incendios en la Roma imperial?',a:['Los vigiles, cohortes creadas por Augusto','Los pretorianos del emperador','Los esclavos de cada casa, sin organización'],ko:'No. Augusto creó los vigiles, siete cohortes de libertos que patrullaban de noche y apagaban los incendios.'}},

{id:'augur',name:'Gneo Domicio Calvino',title:'Augur',glyph:'G',look:Object.assign({},TOGA,{himation:'#e9dcc0',beard:false,hair:'#cfcfc8',staff:true}),
 cat:'Religión',lesson:'La religión romana',where:'En el Capitolio, ante el templo de Júpiter',
 summary:'La religión romana era sobre todo un conjunto de ritos públicos para mantener la pax deorum, la buena relación con los dioses. Los colegios de sacerdotes (pontífices, augures, flámines) eran cargos de la élite política. Los augures interpretaban la voluntad de los dioses observando el vuelo de las aves desde un espacio consagrado; los arúspices leían las entrañas de las víctimas. En cada casa se honraba a los lares, los penates y el genio del padre de familia.',
 intro:'Silencio un momento: estoy observando el cielo. Bien, no hay aves. Soy augur, del colegio de los augures, como lo fueron Cicerón o el divino Augusto. Desde este lugar consagrado, con mi bastón curvo, el lituo, miro qué aves vuelan y por dónde. Antes de cualquier asunto público hay que saber si los dioses están de acuerdo.',
 topics:[
  ['¿Cómo se consulta a los dioses?','Con el lituo trazo en el cielo un espacio sagrado, un templum. Luego observo: qué aves aparecen, de qué lado, cómo vuelan o cantan. También están los pollos sagrados: si comen con ganas antes de la batalla, buena señal. Un cónsul, Claudio Pulcro, los tiró al mar porque no comían, diciendo: «Que beban». Perdió la flota. No se juega con los dioses.'],
  ['¿Qué es la pax deorum?','La paz con los dioses. Roma tiene un pacto con ellos: nosotros les damos los ritos exactos, en el momento justo, con las palabras justas, y ellos protegen la ciudad. Si un prodigio, una estatua que suda sangre o un rayo en el Capitolio, indica que se han enfadado, se consulta a los sacerdotes y se expía. No importa tanto lo que creas en tu interior como que se haga bien el rito. Por eso un error en una palabra obliga a empezar de nuevo.'],
  ['¿A qué dioses adoráis?','A Júpiter Óptimo Máximo, aquí en el Capitolio, con Juno y Minerva. A Marte, padre de Rómulo; a Vesta, el hogar de Roma; a Jano, el de las dos caras. En casa, a los lares, que protegen a la familia, a los penates de la despensa y al genio del padre. Y a los emperadores divinizados: el divino Julio, el divino Augusto, el divino Vespasiano. Acogemos también dioses de fuera, como Cibeles de Frigia o Isis de Egipto. Roma tiene sitio para todos, si respetan a los suyos.']],
 quiz:{q:'¿Qué observaban los augures para conocer la voluntad de los dioses?',a:['El vuelo y el canto de las aves','Las estrellas en el horizonte','El color del humo de los altares'],ko:'No. Los augures interpretaban los auspicios observando el vuelo y el canto de las aves desde un espacio consagrado.'}},

{id:'junia',name:'Junia',title:'Cristiana del Trastévere',glyph:'J',look:{female:true,chiton:'#d8c9a8',himation:'#5c6b5a',veil:true,hair:'#2a1a12'},
 cat:'Religión',lesson:'Judíos y cristianos en Roma',where:'En el Trastévere, al otro lado del Tíber',
 summary:'En Roma vivía una gran comunidad judía, sobre todo en el Trastévere, con varias sinagogas. De ella surgieron los primeros cristianos, seguidores de Jesús de Nazaret. Pablo de Tarso escribió hacia el 57 una carta a los cristianos de Roma y estuvo allí preso hacia el 60-62. Tras el incendio del 64, Nerón culpó a los cristianos y ejecutó a muchos. En el 80 eran todavía un grupo pequeño que se reunía en casas privadas.',
 intro:'La paz sea contigo, forastero. Me llamo Junia. Vivo aquí, en el Trastévere, entre tintoreros, curtidores y judíos de Siria. El primer día de la semana nos reunimos en casa de unos amigos para partir el pan en memoria de un maestro de Galilea. No te lo digo para convencerte; te lo digo porque has preguntado.',
 topics:[
  ['¿Quiénes sois?','Seguimos a Jesús de Nazaret, un maestro judío que murió crucificado en Judea cuando Tiberio era emperador. Decimos que resucitó. Al principio todos éramos judíos; ahora hay también griegos, libertos, esclavos y alguna matrona. Nos reunimos en las casas, cantamos, leemos las escrituras y las cartas de los apóstoles. No tenemos templos ni sacrificios, y por eso algunos nos llaman ateos.'],
  ['¿Qué pasó en tiempos de Nerón?','Después del incendio, la gente decía que Nerón lo había provocado. Él buscó culpables y señaló a los cristianos. A algunos los cubrieron con pieles de animales para que los despedazaran los perros; a otros los crucificaron, o los quemaron de noche para alumbrar sus jardines, al otro lado del Tíber. La tradición dice que entonces murieron también Pedro, el pescador, y Pablo, decapitado en la vía de Ostia. Yo era niña. Mi madre me tapaba los ojos.'],
  ['¿Y los judíos de Roma?','Son muchos, desde hace más de cien años: César los protegió y ellos lloraron en su funeral. Tienen sus sinagogas, guardan el sábado, no comen cerdo. Pero desde la destrucción del Templo de Jerusalén, cada judío del imperio paga un impuesto para el templo de Júpiter Capitolino, y eso es una humillación. Algunos nos miran a nosotros con desconfianza, y los romanos no saben distinguirnos.']],
 quiz:{q:'¿A quién culpó Nerón del incendio de Roma del año 64?',a:['A los cristianos','A los judíos de Alejandría','A los senadores conspiradores'],ko:'No. Según Tácito, Nerón culpó a los cristianos del incendio del 64 y ordenó ejecutar a muchos de ellos de forma cruel.'}},
{id:'sarapion',name:'Sarapión',title:'Sacerdote de Isis',glyph:'S',look:{chiton:'#f3eee2',himation:'#f3eee2',hair:'#a07a5a',beard:false},
 cat:'Religión',lesson:'Isis y Serapis en Roma',where:'En el Iseo del Campo de Marte',
 summary:'Isis, la gran diosa egipcia, esposa de Osiris y madre de Horus, se convirtió en época helenística en una diosa universal, protectora de los marineros, de las madres y de los que sufren. Su culto llegó a Italia con los comerciantes y en Roma tuvo devotos desde el siglo I a.C., pese a las prohibiciones: el Senado derribó varias veces sus altares, Augusto prohibió sus ritos dentro del pomerio y Tiberio destruyó su templo en el 19 d.C. Con Calígula se levantó el gran Iseo del Campo de Marte, y los Flavios lo favorecieron: Vespasiano y Tito pasaron en él la noche antes de su triunfo del 71. Sus sacerdotes llevaban la cabeza afeitada y vestidos de lino, y tocaban el sistro. Las fiestas principales eran la Nave de Isis, en marzo, y las Isias, a finales de octubre.',
 intro:'Que Isis te sea propicia, forastero. Soy Sarapión, servidor de la diosa en este templo. Nací en Alejandría, como mi padre, pero mis fieles son de todas partes: libertos, matronas, soldados, marineros. ¿Ves los obeliscos y las esfinges? Aquí, en medio de Roma, hay un pedazo de Egipto.',
 topics:[
  ['¿Quién es Isis?','La gran diosa de Egipto, esposa de Osiris y madre de Horus. Cuando Set mató a Osiris y lo despedazó, Isis buscó sus restos por todo Egipto, lo devolvió a la vida y concibió a su hijo. Por eso es la madre que consuela, la señora de la magia, la que protege a los marineros y a los que sufren. A su lado veneramos a Serapis, el dios que los reyes de Alejandría unieron con Osiris, y a Anubis, con cabeza de chacal. Sus devotos la llaman «la de los mil nombres».'],
  ['¿Por qué tanto recelo en Roma?','Porque somos extranjeros y algunas de nuestras fiestas son de noche. El Senado mandó derribar los altares de Isis en el Capitolio varias veces, hace más de un siglo. Augusto prohibió nuestros ritos dentro del recinto sagrado de la ciudad. Y Tiberio, después de que unos sacerdotes ayudaran a un caballero a engañar a una dama devota en el templo, los mandó crucificar y echó la estatua de la diosa al Tíber. Aun así volvimos: este templo se levantó en tiempos de Calígula.'],
  ['¿Y los emperadores de ahora?','Nos quieren bien. La noche antes de su triunfo sobre Judea, Vespasiano y Tito la pasaron aquí, en el Iseo. En Alejandría, dicen, Vespasiano curó a un ciego siguiendo el consejo de Serapis. Y Domiciano, el hermano del emperador, se salvó en la guerra del 69 escapando del Capitolio en llamas disfrazado de sacerdote de Isis. El incendio de este año ha dañado el templo; esperamos que lo reconstruyan.'],
  ['¿Qué fiestas celebráis?','El 5 de marzo, la Nave de Isis: vamos en procesión hasta el agua y botamos una nave nueva cargada de ofrendas, porque la diosa abre la navegación. Y a finales de octubre, las Isias: lloramos durante días la muerte de Osiris, lo buscamos como lo buscó Isis, y al final gritamos de alegría: «¡Lo hemos encontrado!». Cada día abrimos el templo al amanecer con el agua sagrada del Nilo y lo cerramos por la tarde, al son del sistro.']],
 quiz:{q:'¿Dónde pasaron Vespasiano y Tito la noche antes de su triunfo del año 71?',a:['En el templo de Isis del Campo de Marte','En el templo de la Gran Madre del Palatino','En la Curia, con los senadores'],ko:'No. Según Flavio Josefo, la pasaron en el Iseo del Campo de Marte, el templo de Isis.'}},
{id:'licinia',name:'Licinia',title:'Devota de la Gran Madre',glyph:'L',look:{female:true,chiton:'#efe6d5',himation:'#5a6a3a',veil:true,hair:'#3b2a1e'},
 cat:'Religión',lesson:'La Gran Madre de los dioses',where:'Ante su templo, en el Palatino',
 summary:'La Gran Madre (Magna Mater, la Cibeles de los griegos) era una diosa de Frigia, en Asia Menor, señora de la naturaleza y protectora de las ciudades. Los romanos la trajeron en el 204 a.C., en plena guerra contra Aníbal, por consejo de los libros sibilinos: su imagen era una piedra negra de Pesinunte. Su templo del Palatino se dedicó en el 191 a.C. y lo reconstruyó Augusto. Cada abril se celebraban en su honor las Megalesias, con obras de teatro. Sus sacerdotes, los galos, eran eunucos frigios que recorrían las calles con tambores y címbalos; a los ciudadanos romanos no se les permitía serlo.',
 intro:'Salve. Soy Licinia, y vengo a menudo a este templo, como venía mi madre. ¿Oyes los tambores? Son los galos, los sacerdotes de la diosa. A mucha gente les dan miedo, pero la Madre del Ida lleva más de doscientos ochenta años protegiendo Roma.',
 topics:[
  ['¿Quién es la Gran Madre?','La madre de todos los dioses, señora de las montañas, de las fieras y de las cosechas. La llamamos Magna Mater, la Gran Madre del Ida; los griegos, Cibeles. Va en un carro tirado por leones y lleva una corona en forma de muralla, porque protege las ciudades. Llegó de Frigia, de Pesinunte, en Asia.'],
  ['¿Cómo llegó a Roma?','En el 204 a.C., en plena guerra contra Aníbal, los libros sibilinos dijeron que el enemigo se iría de Italia si se traía a Roma a la Madre del Ida. El rey Átalo de Pérgamo nos entregó su imagen: una piedra negra caída del cielo. La recibió Escipión Nasica, elegido como el mejor de los romanos. Cuando la nave encalló en el Tíber, una matrona acusada de no ser casta, Claudia Quinta, la sacó tirando de una cuerda, y así demostró su inocencia. Al año siguiente Aníbal se fue de Italia.'],
  ['¿Quiénes son esos sacerdotes?','Los galos, sus sacerdotes frigios. Se han castrado en honor de Atis, el joven pastor amado por la diosa. Llevan el pelo largo, ropas de colores y joyas, y recorren las calles con tambores, címbalos y flautas, bailando y pidiendo limosna. A un ciudadano romano no se le permite hacerse galo: nosotros veneramos a la diosa a la manera romana, con sacrificios y juegos.'],
  ['¿Qué son las Megalesias?','Los juegos de la diosa, del 4 al 10 de abril: procesión, banquetes entre las familias nobles y obras de teatro aquí delante, con el público sentado en la escalinata del templo. Aquí se estrenaron comedias de Plauto y de Terencio. Y en marzo, dicen que desde tiempos de Claudio, se llora la muerte de Atis y se celebra su vuelta a la vida.']],
 quiz:{q:'¿Por qué trajeron los romanos a la Gran Madre en el 204 a.C.?',a:['Porque los libros sibilinos lo aconsejaban para vencer a Aníbal','Para celebrar la conquista de Egipto','Porque se lo pidió el rey de Siria'],ko:'No. Fue en plena guerra contra Aníbal: los libros sibilinos dijeron que el enemigo se iría de Italia si se traía a la Madre del Ida.'}},
{id:'debora',name:'Débora',title:'Tejedora judía del Trastévere',glyph:'D',look:{female:true,chiton:'#e8dfcc',himation:'#3a4a6a',veil:true,hair:'#2a1a12'},
 cat:'Religión',lesson:'La comunidad judía de Roma',where:'Ante la sinagoga, en el Trastévere',
 summary:'Los judíos de Roma eran una comunidad grande y antigua, sobre todo en el Trastévere: muchos descendían de prisioneros traídos por Pompeyo en el 63 a.C. y luego liberados. Hablaban sobre todo griego y se organizaban en varias sinagogas, donde se leía la Ley cada sábado. César y Augusto les reconocieron el derecho a reunirse y a enviar dinero al Templo de Jerusalén; Tiberio y Claudio los expulsaron por un tiempo. Tras la destrucción del Templo en el 70, Vespasiano obligó a todos los judíos del Imperio a pagar dos dracmas al año para el templo de Júpiter Capitolino, y miles de prisioneros de la guerra fueron vendidos como esclavos. Algunos romanos, llamados «temerosos de Dios», frecuentaban las sinagogas sin convertirse.',
 intro:'Shalom, forastero. Soy Débora; tejo y vendo telas aquí, en el Trastévere, como mi madre y mi abuela. Esa casa es nuestra sinagoga, nuestra casa de oración. Si vienes en sábado la encontrarás llena; hoy solo están los niños aprendiendo a leer.',
 topics:[
  ['¿Qué hacéis en la sinagoga?','Cada sábado nos reunimos para leer la Ley de Moisés y los Profetas, en griego, que es la lengua de casi todos nosotros, y para rezar y escuchar a los que la explican. Pero la sinagoga es también nuestra escuela, nuestro tribunal y nuestra casa común: allí se recogen limosnas, se acoge a los viajeros y se decide lo de la comunidad. En Roma hay varias, cada una con su nombre: la de los Augustenses, la de los Agripenses, la de los Hebreos…'],
  ['¿Cómo es vuestro sábado?','El séptimo día no trabajamos ni encendemos fuego: es un día de descanso para todos, también para los esclavos y los animales. Algunos romanos se burlan y dicen que somos unos perezosos; el divino Augusto creía, ¡pobre!, que ayunábamos ese día. Pero él fue justo con nosotros: si el reparto de trigo caía en sábado, mandaba guardarnos la ración para el día siguiente.'],
  ['¿Qué ha cambiado desde la guerra?','Todo. El Templo de Jerusalén ya no existe. Antes cada uno de nosotros enviaba medio siclo al año para el Templo; ahora Vespasiano nos obliga a pagar dos dracmas para el templo de Júpiter Capitolino, el de ellos. Por las calles vimos pasar en el triunfo los objetos sagrados, y el candelabro está expuesto en el Templo de la Paz. Y llegaron miles de prisioneros: hemos reunido dinero para comprar y liberar a todos los que hemos podido.'],
  ['¿Hay romanos que se interesan por vuestra fe?','Más de los que crees. Vienen a la sinagoga, guardan el sábado, no comen cerdo; los llamamos «temerosos de Dios». Algunos se convierten del todo. Dicen que Popea, la esposa de Nerón, nos tenía simpatía. A otros, en cambio, les parecemos extraños: no ponemos imágenes de nuestro Dios, no comemos con todos y no veneramos a los dioses de la ciudad.']],
 quiz:{q:'¿Qué impuesto pagan los judíos del Imperio desde el año 70?',a:['Dos dracmas al año para el templo de Júpiter Capitolino','Una décima parte de sus cosechas para el emperador','Ninguno: están exentos por la guerra'],ko:'No. Vespasiano obligó a todos los judíos a pagar dos dracmas al año para el templo de Júpiter Capitolino, en lugar del medio siclo que antes enviaban al Templo de Jerusalén.'}},

{id:'medico',name:'Asclepíades',title:'Médico griego',glyph:'Α',look:{chiton:'#efe8da',himation:'#6a7f5a',beard:true,hair:'#8d8a85',beardC:'#9a968e'},
 cat:'Ciencia',lesson:'La medicina en Roma',where:'En la Isla Tiberina, junto al templo de Esculapio',
 summary:'La medicina romana era sobre todo griega: los médicos más prestigiosos eran griegos, a menudo esclavos o libertos. Conocían la teoría de los cuatro humores de Hipócrates, operaban con instrumentos de bronce y usaban muchas plantas medicinales. En la Isla Tiberina estaba el templo de Esculapio, traído de Epidauro en el 291 a.C. tras una peste; allí se abandonaba a los esclavos enfermos, hasta que Claudio decretó que quedaban libres si se curaban.',
 intro:'Salud, que es lo mío. Me llamo Asclepíades, como el gran médico de Bitinia, aunque yo soy de Pérgamo. Aquí, en la isla de Esculapio, atiendo a los enfermos que vienen a dormir en el templo esperando un sueño del dios. Yo prefiero las hierbas y el bisturí, pero no le quito el trabajo al dios.',
 topics:[
  ['¿Por qué el templo está en una isla?','Hace casi cuatrocientos años, una peste asolaba Roma y los libros sibilinos mandaron traer a Esculapio de Epidauro. Fue una embajada en barco y, al volver, una serpiente sagrada saltó del barco y nadó hasta esta isla. Aquí se construyó el templo. Por eso la isla se ha adornado con forma de barco, con una proa de travertino, y en ella el bastón con la serpiente.'],
  ['¿Cómo curáis?','Según Hipócrates, la salud es el equilibrio de cuatro humores: sangre, flema, bilis amarilla y bilis negra. La enfermedad es un desequilibrio, y se corrige con dieta, ejercicio, baños, sangrías, purgas y medicinas de plantas: adormidera para el dolor, mandrágora para dormir. Y si hace falta, operamos: cataratas, piedras, heridas, amputaciones. Tengo pinzas, sondas, escalpelos y espéculos de bronce. Contra el dolor de verdad solo tenemos el vino y el opio.'],
  ['¿Qué pasa con los esclavos enfermos?','Algunos amos abandonan aquí, en la isla, a sus esclavos enfermos o viejos para no tener que cuidarlos. El emperador Claudio decretó que el esclavo abandonado que se curara quedaba libre, y que el amo que lo matara en vez de abandonarlo sería acusado de asesinato. Así que muchos que llegan aquí como esclavos salen libres. Si salen.']],
 quiz:{q:'Según la medicina de Hipócrates, ¿qué era la salud?',a:['El equilibrio de los cuatro humores del cuerpo','La ausencia de demonios en el cuerpo','Un regalo exclusivo del emperador'],ko:'No. Para la medicina hipocrática, la salud era el equilibrio entre cuatro humores: sangre, flema, bilis amarilla y bilis negra.'}}
];
